-- Lot 1 : fermeture des 8577 biens actifs en base mais disparus (404 > 48 h) ou fermes cote Yanport.
-- Audit lecture seule du 2026-11-22 : 56247 candidats actifs (hors P_EstRattrapage = 4),
--   8113 absents 404 (> 48 h), 464 fermes Yanport, 123 absents < 48 h exclus par delai de grace.
-- A executer UNIQUEMENT sur ordre ecrit explicite de l utilisateur.
-- Ne supprime aucune ligne property, ne touche pas P_DateLastUpdate, ne touche pas P_EstRattrapage = 4.
-- Retour arriere : infra/ovh/sql/20261122-yanport-ghosts-close-rollback.sql

-- Test a blanc (SELECT uniquement, avant ecriture) :
-- SELECT COUNT(*) AS actifs_avant FROM property WHERE P_State = 1 AND (P_DateFin IS NULL OR P_DateFin < '1000-01-01') AND IFNULL(P_EstRattrapage, 0) <> 4;

CREATE TABLE IF NOT EXISTS backup_property_20261122_yanport_ghosts (
  P_PropertyId VARCHAR(40) NOT NULL PRIMARY KEY,
  close_reason VARCHAR(20) NOT NULL,
  yanport_end_date DATETIME NULL,
  old_state INT UNSIGNED NULL,
  old_date_fin DATETIME NULL,
  old_rattrapage TINYINT NULL,
  captured_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

START TRANSACTION;

