-- Capture de l etat exact avant modification pour un retour arriere 1:1.
UPDATE backup_property_20261122_yanport_ghosts b
INNER JOIN property p ON p.P_PropertyId = b.P_PropertyId
SET b.old_state = p.P_State,
    b.old_date_fin = p.P_DateFin,
    b.old_rattrapage = p.P_EstRattrapage
WHERE b.old_state IS NULL
  AND p.P_State = 1
  AND (p.P_DateFin IS NULL OR p.P_DateFin < '1000-01-01')
  AND IFNULL(p.P_EstRattrapage, 0) <> 4;

SELECT close_reason, COUNT(*) AS captured_rows
FROM backup_property_20261122_yanport_ghosts
WHERE old_state = 1
GROUP BY close_reason;

-- Fermeture securisee (idempotente, P_EstRattrapage = 5, P_DateLastUpdate inchange).
UPDATE property p
INNER JOIN backup_property_20261122_yanport_ghosts b ON b.P_PropertyId = p.P_PropertyId
SET p.P_State = 0,
    p.P_DateFin = COALESCE(b.yanport_end_date, p.P_DateLastUpdate, NOW()),
    p.P_EstRattrapage = 5
WHERE b.old_state = 1
  AND p.P_State = 1
  AND (p.P_DateFin IS NULL OR p.P_DateFin < '1000-01-01')
  AND IFNULL(p.P_EstRattrapage, 0) <> 4;

SELECT ROW_COUNT() AS updated_rows;

SELECT p.P_State, p.P_EstRattrapage, COUNT(*) AS n
FROM property p
INNER JOIN backup_property_20261122_yanport_ghosts b ON b.P_PropertyId = p.P_PropertyId
WHERE b.old_state = 1
GROUP BY p.P_State, p.P_EstRattrapage;

COMMIT;
